param([Parameter(Mandatory=$true)][string]$NodeExecutable,[Parameter(Mandatory=$true)][string]$Config,[Parameter(Mandatory=$true)][string]$Output)
$ErrorActionPreference='Stop';$configValue=Get-Content -LiteralPath $Config -Raw -Encoding UTF8|ConvertFrom-Json;$before=[Console]::OutputEncoding.CodePage;$results=@()
foreach($case in $configValue.cases){$value=(& $NodeExecutable $configValue.profile verify --envelope $case.envelope --expected-envelope-sha256 $case.sha256 | Out-String)|ConvertFrom-Json;if($LASTEXITCODE -ne 0){throw 'Actual profile CLI failed'};$expected=Get-Content -LiteralPath $case.expectation -Raw -Encoding UTF8|ConvertFrom-Json;$actualText=$value.expectation|ConvertTo-Json -Compress -Depth 100;$expectedText=$expected|ConvertTo-Json -Compress -Depth 100;if(-not [string]::Equals($actualText,$expectedText,[StringComparison]::Ordinal)){throw ('Full source expectation changed across native pipe: '+$case.id)};$results+=@([ordered]@{id=$case.id;wholeExpectationEqual=$true;shapeCount=$value.expectation.shapeCount;firstTextUnits=@($value.expectation.shapes[0].text.ToCharArray()|ForEach-Object{[int]$_})})}
$actual=(& $NodeExecutable $configValue.payload | Out-String)|ConvertFrom-Json;if($LASTEXITCODE -ne 0){throw 'Payload CLI failed'};$expected=$configValue.expectedPayload;$payloadResults=@();foreach($property in $expected.PSObject.Properties){$a=$actual.($property.Name);$e=$property.Value;if(-not [string]::Equals($a,$e,[StringComparison]::Ordinal)){throw ('Unicode code units changed: '+$property.Name)};$payloadResults+=@([ordered]@{name=$property.Name;units=@($a.ToCharArray()|ForEach-Object{[int]$_});equal=$true})}
if([Console]::OutputEncoding.CodePage -ne $before){throw 'Console encoding changed'}
[ordered]@{status='PASS';officeInvoked=$false;liveProcessQueries=0;psVersion=$PSVersionTable.PSVersion.ToString();consoleOutputCodePage=$before;encodingChanged=$false;actualProfileCases=$results;payloadCases=$payloadResults}|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $Output -Encoding UTF8
Write-Output 'PASS5 complete source expectations and8 Unicode code-unit payloads through actual PS5 native Node pipes'
